import argparse
from collections import defaultdict

def main():
    parser = argparse.ArgumentParser(description="Count whitespace-separated integers and print each value and count separated by one space in numeric order.")
    parser.add_argument("--min", type=int, help="Drop values below the supplied integer.")
    args = parser.parse_args()

    counts = defaultdict(int)
    for line in sys.stdin:
        for word in line.split():
            try:
                number = int(word)
                if args.min is not None and number < args.min:
                    continue
                counts[number] += 1
            except ValueError:
                continue

    for number in sorted(counts.keys()):
        print(f"{number} {counts[number]}")

if __name__ == "__main__":
    main()

import json
import sys

def load_bookmarks(file_path):
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        return {}

def save_bookmarks(file_path, bookmarks):
    with open(file_path, 'w') as file:
        json.dump(bookmarks, file, indent=4)

def add_bookmark(bookmarks, name, url):
    bookmarks[name] = url
    save_bookmarks('bookmarks.json', bookmarks)
    print(f"Added {name} -> {url}")

def list_bookmarks(bookmarks):
    for name, url in sorted(bookmarks.items()):
        print(f"{name}\t{url}")

def remove_bookmark(bookmarks, name):
    if name in bookmarks:
        del bookmarks[name]
        save_bookmarks('bookmarks.json', bookmarks)
        print(f"Removed {name}")
    else:
        print(f"Error: {name} not found")

def main():
    if len(sys.argv) < 2:
        print("Usage: python bookmark_manager.py <json_file>")
        sys.exit(1)

    file_path = sys.argv[1]
    bookmarks = load_bookmarks(file_path)

    while True:
        command = input("Enter command (add NAME URL, list, remove NAME, exit): ").strip().lower()

        if command == "exit":
            break

        if command == "add":
            name = input("Enter name: ").strip()
            url = input("Enter URL: ").strip()
            add_bookmark(bookmarks, name, url)
        elif command == "list":
            list_bookmarks(bookmarks)
        elif command.startswith("remove"):
            name = command.split()[1]
            remove_bookmark(bookmarks, name)
        else:
            print("Error: Invalid command")

if __name__ == "__main__":
    main()

