def main():
    category = sys.argv[1] if len(sys.argv) > 1 else None
    expenses = []
    total_by_category = {}

    for line in sys.stdin:
        expense = line.strip().split(',')
        if len(expense) == 2:
            amount = float(expense[1])
            expenses.append((expense[0], amount))
            if category and expense[0] == category:
                total_by_category[category] = total_by_category.get(category, 0) + amount

    if category:
        print(json.dumps({category: total_by_category.get(category, 0)}))
    else:
        totals = {category: total_by_category.get(category, 0) for category in total_by_category}
        print(json.dumps(totals))

if __name__ == "__main__":
    main()

import sys

def print_board(board):
    for row in board:
        print(" ".join(row))

def check_win(board, player):
    # Check rows
    for row in board:
        if all(cell == player for cell in row):
            return True
    # Check columns
    for col in range(3):
        if all(board[row][col] == player for row in range(3)):
            return True
    # Check diagonals
    if all(board[i][i] == player for i in range(3)) or all(board[i][2-i] == player for i in range(3)):
        return True
    return False

def check_draw(board):
    return all(cell != "" for row in board for cell in row)

def get_player_input(board):
    while True:
        try:
            move = int(input("Enter your move (1-9): "))
            if move < 1 or move > 9 or board[(move-1)//3][(move-1)%3] != "":
                print("Invalid move or square already occupied. Try again.")
            else:
                return move
        except ValueError:
            print("Invalid input. Please enter a number between 1 and 9.")

def switch_player(player):
    return 'O' if player == 'X' else 'X'

def main():
    board = [["" for _ in range(3)] for _ in range(3)]
    player = 'X'
    print_board(board)
    while True:
        move = get_player_input(board)
        board[(move-1)//3][(move-1)%3] = player
        print_board(board)
        if check_win(board, player):
            print(f"{player} wins!")
            break
        elif check_draw(board):
            print("Draw!")
            break
        player = switch_player(player)

if __name__ == "__main__":
    main()

import argparse
import json
import os

def get_directory_inventory(directory, suffix=None):
    inventory = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            if suffix and not file.endswith(suffix):
                continue
            file_path = os.path.join(root, file)
            if os.path.isfile(file_path):
                inventory[file_path] = os.path.getsize(file_path)
    return inventory

def main():
    parser = argparse.ArgumentParser(description="Directory Inventory")
    parser.add_argument("directory", help="Directory to inventory")
    parser.add_argument("--suffix", help="Suffix to filter files by")
    args = parser.parse_args()

    inventory = get_directory_inventory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

if __name__ == "__main__":
    main()

import argparse
import json
import sys

def validate_transaction(transaction):
    if not transaction:
        return False
    if not isinstance(transaction, dict) or 'id' not in transaction or 'cents' not in transaction:
        return False
    if not isinstance(transaction['id'], str) or not isinstance(transaction['cents'], int):
        return False
    return True

def main():
    parser = argparse.ArgumentParser(description='Validate transactions in a JSONL file')
    parser.add_argument('file', type=str, help='JSONL file containing transactions')
    args = parser.parse_args()

    total_cents = 0
    line_number = 0

    try:
        with open(args.file, 'r') as file:
            for line in file:
                line_number += 1
                transaction = json.loads(line.strip())
                if not validate_transaction(transaction):
                    print(f"Invalid transaction on line {line_number}: {transaction}", file=sys.stderr)
                    sys.exit(1)
                total_cents += transaction['cents']
    except FileNotFoundError:
        print(f"File not found: {args.file}", file=sys.stderr)
        sys.exit(1)

    print(f"Total cents: {total_cents}")

if __name__ == "__main__":
    main()

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <json_file>")
        sys.exit(1)

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print(f"Error: File {json_file} not found.")
        sys.exit(1)

    score = 0
    for question in data:
        print(question["question"])
        answers = question["answers"]
        correct_answer = answers[0].lower()
        for answer in answers[1:]:
            if answer.lower() == correct_answer:
                correct_answer = answer.lower()
        user_answer = input().lower()
        if user_answer == correct_answer:
            score += 1
    print(f"Score: {score}/{len(data)}")

if __name__ == "__main__":
    main()
